<script setup>
import { reactive, computed, ref } from 'vue'
import Icon from './Icon.vue'
import { today, clone, total, round, cents, money, statuses } from '../utils'
const props = defineProps({ order: Object, initialStyle: Object, styles: Array, busy: Boolean, upload: Function, error: String })
const emit = defineEmits(['save','cancel','view-photo'])
const p = props.initialStyle
const form = reactive(props.order ? { ...clone(props.order), receiptDate: today() } : { id:'', date:today(), customer:'', style:p?.name||'', styleIds:p?[p.id]:[], price:p?.price||0, deposit:0, final:0, discount:0, cost:p?.cost||0, due:'', status:'booked', channel:'微信', address:'', tracking:'', note:'', photos:[], product:p?.artId??null, receiptDate:today() })
const uploading = ref(false), localError = ref('')
const left = computed(() => (cents(form.price)-cents(form.deposit)-cents(form.final)-cents(form.discount))/100)
const amountFields = [['price','订单报价（元）*'],['discount','抹零 / 优惠（元）'],['deposit','已收定金（元）'],['final','已收尾款（元）']]
function selectStyle(p) { const i=form.styleIds.indexOf(p.id); if(i>=0)form.styleIds.splice(i,1);else form.styleIds.push(p.id);const selected=props.styles.filter(p=>form.styleIds.includes(p.id));form.style=selected.map(p=>p.name).join(' + ');form.price=total(selected,p=>p.price||0);form.cost=total(selected,p=>p.cost||0);form.product=selected[0]?.artId??null }
function roundOff() { if(left.value>0)form.discount=(cents(form.discount)+cents(left.value)%100)/100 }
async function addPhotos(event) { const files=[...event.target.files]; localError.value='';if(files.length+form.photos.length>6){localError.value='每笔订单最多 6 张照片。';event.target.value='';return} uploading.value=true;try {for(const file of files){if(file.size>12*1024*1024)throw new Error('单张照片不能超过 12 MB。');form.photos.push(await props.upload(file))}} catch(e){localError.value=e.message} finally {uploading.value=false;event.target.value=''} }
function submit() { localError.value='';if(left.value<0){localError.value='已收定金、尾款和优惠不能超过报价。';return}const payload={};for(const key of ['id','date','customer','style','price','deposit','final','discount','cost','due','status','channel','address','tracking','note','photos','styleIds','product','receiptDate'])payload[key]=form[key];emit('save',payload) }
</script>
<template><form id="order-form" @submit.prevent="submit"><div class="dialog-body"><section class="form-section"><h3><span>01</span>这份喜欢，来自谁</h3><div class="form-grid"><label class="field">下单日期 *<input name="date" type="date" v-model="form.date" required></label><label class="field">订单编号<input name="id" v-model="form.id" maxlength="100" pattern="[\w.\-\u4e00-\u9fff]*" placeholder="留空自动生成"></label><label class="field full">客户名称 / 昵称 *<input name="customer" v-model="form.customer" maxlength="80" placeholder="怎么称呼这位朋友" required></label><label class="field full">包包款式 / 规格 *<textarea name="style" v-model="form.style" rows="2" maxlength="1000" placeholder="手动填写，或点选常用款式" required></textarea></label></div><div class="style-picker"><p class="field-hint">常用款式 · 可多选，报价自动相加</p><div class="chip-list"><button v-for="p in styles" :key="p.id" type="button" class="style-chip" :class="{selected:form.styleIds.includes(p.id)}" :aria-pressed="form.styleIds.includes(p.id)" @click="selectStyle(p)">{{p.name}} <small v-if="p.price!==null">¥{{money(p.price)}}</small></button><p v-if="!styles.length" class="field-hint">还没有常用款式，可以先手动填写。工作室里可管理款式和单价。</p></div></div></section><section class="form-section"><h3><span>02</span>这笔钱，记清楚</h3><div class="form-grid"><label v-for="[key,label] in amountFields" :key="key" class="field">{{label}}<input :name="key" v-model.number="form[key]" type="number" min="0" max="9999999" step="0.01" inputmode="decimal" required></label></div><div class="money-shortcuts"><span>定金</span><button v-for="n in [25,10,0]" :key="n" type="button" class="chip" @click="form.deposit=n">{{n?'¥'+n:'无定金'}}</button><button type="button" class="chip" @click="roundOff">抹掉待收零头</button></div><div class="money-summary" aria-live="polite"><div><small>报价 − 定金</small><strong>¥{{money(round(form.price-form.deposit))}}</strong></div><div><small>抹零 / 优惠</small><strong>¥{{money(form.discount)}}</strong></div><div :class="{'balance-warn':left!==0}"><small>待收尾款</small><strong>¥{{money(left)}}</strong></div></div><label class="field receipt-date">{{order?'本次新增收款 / 优惠日期':'收款 / 优惠日期'}}<input name="receiptDate" v-model="form.receiptDate" type="date" required><small class="field-hint">已有流水日期保持不变；可到收支页逐笔编辑。</small></label></section><section class="form-section"><h3><span>03</span>制作与交付</h3><div class="form-grid"><label class="field">订单状态<select name="status" v-model="form.status"><option v-for="(label,key) in statuses" :key="key" :value="key">{{label}}</option></select></label><label class="field">预计交付日期<input name="due" type="date" v-model="form.due"></label><label class="field full">收货信息（姓名 / 电话 / 地址）<textarea name="address" v-model="form.address" rows="3" maxlength="1000" placeholder="粘贴顾客完整收货信息，发货时可一键复制"></textarea></label><label class="field">快递单号<input name="tracking" v-model="form.tracking" maxlength="100"></label><label class="field">来自哪里<input name="channel" v-model="form.channel" maxlength="80"></label><label class="field full">预估直接成本（元）<input name="cost" v-model.number="form.cost" type="number" min="0" max="9999999" step="0.01" inputmode="decimal" required></label></div></section><section class="form-section"><h3><span>04</span>留住成品的样子</h3><p class="field-hint">最多 6 张，自动压缩后保存在电脑的 images 目录。</p><div class="photo-grid"><div v-for="(url,i) in form.photos" :key="url" class="photo-tile"><button type="button" :aria-label="'放大照片 '+(i+1)" @click="emit('view-photo',url)"><img :src="url" :alt="'成品照片 '+(i+1)"></button><button type="button" class="remove-photo" :aria-label="'移除照片 '+(i+1)" @click="form.photos.splice(i,1)">×</button></div></div><label class="photo-upload" :class="{disabled:uploading}"><Icon name="plus" />{{uploading?'正在上传…':'添加照片'}}<input id="photo-input" type="file" accept="image/jpeg,image/png,image/webp" multiple :disabled="uploading||busy" @change="addPhotos"></label><p v-if="form.photos.length" class="field-hint">已添加 {{form.photos.length}} / 6 张</p><label class="field note-field">备注 / 定制细节<textarea name="note" v-model="form.note" rows="3" maxlength="2000" placeholder="颜色、尺寸、口袋，或特别记住的小细节…"></textarea></label></section><p class="form-note">定金和尾款自动计入收支，不用再记一次。优惠不算收入，实际采购单独记支出。</p><p v-if="error||localError" class="inline-error" role="alert">{{error||localError}}</p></div><div class="dialog-footer"><button type="button" class="btn" :disabled="busy||uploading" @click="emit('cancel')">取消</button><button class="btn btn-primary" type="submit" :disabled="busy||uploading"><Icon name="check" />{{busy?'正在保存…':order?'保存修改':'记下这份订单'}}</button></div></form></template>
